1	package handover
2	
3	import (
4		"fmt"
5		"sort"
6		"strings"
7		"time"
8	)
9	
10	// Service 在 Store 之上实现班次交接的全部业务规则。
11	type Service struct {
12		store *Store
13		now   func() time.Time
14	}
15	
16	// NewService 创建业务服务。
17	func NewService(store *Store) *Service {
18		return &Service{store: store, now: time.Now}
19	}
20	
21	// nowAt 供测试固定处理时间。
22	func (svc *Service) nowAt(fn func() time.Time) { svc.now = fn }
23	
24	func clean(s string) string { return strings.TrimSpace(s) }
25	
26	// 事项历史中的接收说明模板。新写入的 received 事件用交接编号、交班、接班班次
27	// 与接收方式完整标注；item-show 合并接收记录时依据这些明确记载判定同一次接收，
28	// 不能仅凭操作人与时刻合并。模板为固定格式，parseReceivedDetail 据其解析。
29	const (
30		receivedDetailPrefix = "交接 "
31		receivedDetailMid    = "（"
32		receivedDetailArrow  = " -> "
33		receivedDetailTail   = "）接班班次接收："
34		// 旧版本写入的说明只明确记载接班班次与接收方式，没有交接编号与交班班次，
35		// 例如“接班班次 S002 接收：确认接收”。其中明确记载的事实仍可用于比对，
36		// 未记载的字段不比较，更不凭空补齐。
37		legacyReceivedPrefix = "接班班次 "
38		legacyReceivedTail   = " 接收："
39	)
40	
41	// receivedDetailText 生成接收事件的标准说明，明确记载交接编号、交班、接班班次
42	// 与接收方式；继续跟踪还保留当时的跟踪说明与后续负责人。
43	func receivedDetailText(h *Handover, action EntryAction, statusLabel, trackingNote, nextFollowOwner string) string {
44		s := receivedDetailPrefix + h.ID + receivedDetailMid + h.FromShiftID +
45			receivedDetailArrow + h.ToShiftID + receivedDetailTail + statusLabel
46		if action == ActionTrack {
47			s += "；跟踪说明：" + trackingNote + "；后续负责人：" + nextFollowOwner
48		}
49		return s
50	}
51	
52	// receivedAttribution 是从接收说明中明确解析出的归属信息。空字符串表示该
53	// 说明没有明确记载这一项，比对时不得据此判断一致或矛盾。
54	type receivedAttribution struct {
55		handoverID string
56		fromShift  string
57		toShift    string
58		kind       string // confirm/track，无法确定时为 ""
59	}
60	
61	// receivedKindFromLabel 只识别两种已保存的接收方式中文名；track 的说明后还
62	// 带有“；跟踪说明：…”后缀。无法识别返回 ""，不据其他信息猜测。
63	func receivedKindFromLabel(label string) string {
64		switch {
65		case label == EntryConfirmed.Label():
66			return "confirm"
67		case label == EntryTracking.Label() || strings.HasPrefix(label, EntryTracking.Label()+"；"):
68			return "track"
69		}
70		return ""
71	}
72	
73	// parseReceivedDetail 只解析本工具写入的固定格式说明（含旧版本格式），提取
74	// 其中明确记载的交接编号、交班、接班班次与接收方式。其他文字（外部写入或
75	// 残缺的说明）一律视为没有明确记载，返回 ok=false，绝不靠猜测补全。
76	func parseReceivedDetail(detail string) (receivedAttribution, bool) {
77		switch {
78		case strings.HasPrefix(detail, receivedDetailPrefix):
79			rest := detail[len(receivedDetailPrefix):]
80			pi := strings.Index(rest, receivedDetailMid)
81			ai := strings.Index(rest, receivedDetailArrow)
82			ti := strings.Index(rest, receivedDetailTail)
83			if pi <= 0 || ai < 0 || ti < 0 || !(pi < ai && ai+len(receivedDetailArrow) < ti) {
84				return receivedAttribution{}, false
85			}
86			hid := rest[:pi]
87			from := rest[pi+len(receivedDetailMid) : ai]
88			to := rest[ai+len(receivedDetailArrow) : ti]
89			kind := receivedKindFromLabel(rest[ti+len(receivedDetailTail):])
90			if hid == "" || from == "" || to == "" || kind == "" {
91				return receivedAttribution{}, false
92			}
93			return receivedAttribution{handoverID: hid, fromShift: from, toShift: to, kind: kind}, true
94		case strings.HasPrefix(detail, legacyReceivedPrefix):
95			rest := detail[len(legacyReceivedPrefix):]
96			ti := strings.Index(rest, legacyReceivedTail)
97			if ti <= 0 {
98				return receivedAttribution{}, false
99			}
100			to := rest[:ti]
101			kind := receivedKindFromLabel(rest[ti+len(legacyReceivedTail):])
102			if to == "" || kind == "" {
103				return receivedAttribution{}, false
104			}
105			// 旧格式只明确记载接班班次与接收方式；交接编号、交班班次未记载。
106			return receivedAttribution{toShift: to, kind: kind}, true
107		}
108		return receivedAttribution{}, false
109	}
110	
111	func requireNonEmpty(field, v string) error {
112		if clean(v) == "" {
113			return fmt.Errorf("%w：%s不能为空", ErrInvalidInput, field)
114		}
115		return nil
116	}
117	
118	func intervalsOverlap(s1, e1, s2, e2 time.Time) bool {
119		// 前班结束恰好等于后班开始（端点相等）不算重叠。
120		return s1.Before(e2) && s2.Before(e1)
121	}
122	
123	// notePair 返回无序班次编号对，作为重叠说明的稳定键。
124	func notePair(a, b string) (string, string) {
125		if a <= b {
126			return a, b
127		}
128		return b, a
129	}
130	
