177	// currentItemsOfShift 返回与某班次相关的当前事项，按编号排列、每项只列一次。
178	// 用于进行中班次的当前信息展示，以及缺少结束时记录的旧数据班次。
179	func currentItemsOfShift(d *Data, shiftID string) []Item {
180		out := []Item{}
181		seen := map[string]bool{}
182		for _, it := range d.Items {
183			if seen[it.ID] {
184				continue
185			}
186			if it.OriginShiftID == shiftID || it.CurrentShiftID == shiftID || contains(it.ShiftIDs, shiftID) {
187				seen[it.ID] = true
188				out = append(out, it)
189			}
190		}
191		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
192		return out
193	}
