1	package handover
2	
3	import (
4		"encoding/json"
5		"errors"
6		"fmt"
7		"os"
8		"path/filepath"
9		"strings"
10		"testing"
11		"time"
12	)
13	
14	type fixture struct {
15		svc   *Service
16		store *Store
17		clock time.Time
18	}
19	
20	func newFixture(t *testing.T) *fixture {
21		t.Helper()
22		dir := t.TempDir()
23		store, err := Open(filepath.Join(dir, "data.json"))
24		if err != nil {
25			t.Fatalf("open: %v", err)
26		}
27		svc := NewService(store)
28		f := &fixture{
29			svc:   svc,
30			store: store,
31			clock: time.Date(2026, 10, 2, 8, 0, 0, 0, time.FixedZone("CST", 8*3600)),
32		}
33		svc.nowAt(func() time.Time {
34			f.clock = f.clock.Add(time.Minute)
35			return f.clock
36		})
37		return f
38	}
39	
40	// reopen 模拟退出后重新打开，数据与处理进度必须仍在。
41	func (f *fixture) reopen(t *testing.T) {
42		t.Helper()
43		store, err := Open(f.store.Path())
44		if err != nil {
45			t.Fatalf("reopen: %v", err)
46		}
47		svc := NewService(store)
48		svc.nowAt(f.svc.now)
49		f.store = store
50		f.svc = svc
51	}
52	
53	func tsDay(day, hour, min int) time.Time {
54		return time.Date(2026, 10, day, hour, min, 0, 0, time.FixedZone("CST", 8*3600))
55	}
56	
57	func ts(hour, min int) time.Time { return tsDay(2, hour, min) }
58	
59	func mustShift(t *testing.T, f *fixture, position, owner string, s, e time.Time, note string) Shift {
60		t.Helper()
61		sh, err := f.svc.CreateShift(position, owner, s, e, note)
62		if err != nil {
63			t.Fatalf("create shift: %v", err)
64		}
65		return sh
66	}
67	
68	func TestCreateShiftValidation(t *testing.T) {
69		f := newFixture(t)
70	
71		if _, err := f.svc.CreateShift("   ", "张三", ts(8, 0), ts(16, 0), ""); !errors.Is(err, ErrInvalidInput) {
72			t.Fatalf("空白岗位应报错， got %v", err)
73		}
74		if _, err := f.svc.CreateShift("调度", "  ", ts(8, 0), ts(16, 0), ""); !errors.Is(err, ErrInvalidInput) {
75			t.Fatalf("空白负责人应报错，got %v", err)
76		}
77		if _, err := f.svc.CreateShift("调度", "张三", ts(16, 0), ts(8, 0), ""); !errors.Is(err, ErrInvalidInput) {
78			t.Fatalf("结束早于开始应报错，got %v", err)
79		}
80		if _, err := f.svc.CreateShift("调度", "张三", ts(8, 0), ts(8, 0), ""); !errors.Is(err, ErrInvalidInput) {
81			t.Fatalf("结束等于开始应报错，got %v", err)
82		}
83	
84		a := mustShift(t, f, "调度", "张三", ts(8, 0), ts(16, 0), "")
85		b := mustShift(t, f, "调度", "李四", ts(16, 0), ts(23, 0), "")
86		if a.ID != "S001" || b.ID != "S002" {
87			t.Fatalf("稳定编号错误：%s %s", a.ID, b.ID)
88		}
89	}
90	
91	func TestOverlapEndpointAndPositions(t *testing.T) {
92		f := newFixture(t)
93		mustShift(t, f, "调度", "张三", ts(8, 0), ts(16, 0), "")
94	
95		// 重叠但没有说明：报错。
96		if _, err := f.svc.CreateShift("调度", "王五", ts(15, 0), ts(22, 0), "   "); !errors.Is(err, ErrOverlap) {
97			t.Fatalf("重叠无说明应报 ErrOverlap，got %v", err)
98		}
99	
100		// 重叠且提供说明：成功并保存说明。
101		overlap, err := f.svc.CreateShift("调度", "王五", ts(15, 0), ts(22, 0), "突发抢修，两班并行一小时")
102		if err != nil {
103			t.Fatalf("重叠带说明应成功，got %v", err)
104		}
105		notes := f.svc.OverlapNotes(overlap.ID)
106		if len(notes) != 1 || notes[0].Note != "突发抢修，两班并行一小时" {
107			t.Fatalf("应能查看说明与涉及班次，got %+v", notes)
108		}
109		if !((notes[0].ShiftA == "S001" && notes[0].ShiftB == overlap.ID) ||
110			(notes[0].ShiftA == overlap.ID && notes[0].ShiftB == "S001")) {
111			t.Fatalf("说明应涉及两个重叠班次，got %+v", notes[0])
112		}
113	
114		// 不同岗位同时间段互不影响。
115		if _, err := f.svc.CreateShift("巡检", "赵六", ts(8, 30), ts(15, 30), ""); err != nil {
116			t.Fatalf("不同岗位不应判定重叠：%v", err)
117		}
118	}
119	
120	func TestAddOverlapNoteValidation(t *testing.T) {
121		f := newFixture(t)
122		a := mustShift(t, f, "调度", "张三", ts(8, 0), ts(16, 0), "")
123		b := mustShift(t, f, "调度", "李四", ts(16, 0), ts(23, 0), "")
124		other := mustShift(t, f, "巡检", "赵六", ts(8, 0), ts(16, 0), "")
125	
126		if _, err := f.svc.AddOverlapNote(a.ID, b.ID, "相邻"); !errors.Is(err, ErrInvalidInput) {
127			t.Fatalf("不重叠班次（端点相接）应拒绝说明，got %v", err)
128		}
129		if _, err := f.svc.AddOverlapNote(a.ID, other.ID, "跨岗位"); !errors.Is(err, ErrPositionMismatch) {
130			t.Fatalf("不同岗位应拒绝，got %v", err)
131		}
132		if _, err := f.svc.AddOverlapNote(a.ID, "S999", "x"); !errors.Is(err, ErrNotFound) {
133			t.Fatalf("不存在编号应 ErrNotFound，got %v", err)
134		}
135		if _, err := f.svc.AddOverlapNote(a.ID, a.ID, "自身"); !errors.Is(err, ErrInvalidInput) {
136			t.Fatalf("同一班次应拒绝，got %v", err)
137		}
138	}
139	
140	func TestItemLifecycleAndClosedShiftImmutability(t *testing.T) {
141		f := newFixture(t)
142		a := mustShift(t, f, "调度", "张三", ts(8, 0), ts(16, 0), "")
143	
144		if _, err := f.svc.AddItem(a.ID, "  ", SeverityNormal, "", "李四"); !errors.Is(err, ErrInvalidInput) {
145			t.Fatalf("空白内容应报错，got %v", err)
146		}
147		if _, err := f.svc.AddItem(a.ID, "跟进1号机", Severity("bad"), "", "李四"); !errors.Is(err, ErrInvalidInput) {
148			t.Fatalf("非法严重程度应报错，got %v", err)
149		}
150		if _, err := f.svc.AddItem(a.ID, "跟进1号机", SeverityNormal, "", "  "); !errors.Is(err, ErrInvalidInput) {
151			t.Fatalf("空白后续负责人应报错，got %v", err)
152		}
153	
154		it, err := f.svc.AddItem(a.ID, "  跟进1号机检修 ", SeverityImportant, "  需停电窗口 ", " 李四 ")
155		if err != nil {
156			t.Fatalf("add item: %v", err)
157		}
158		if it.ID != "I001" {
159			t.Fatalf("事项稳定编号应为 I001，got %s", it.ID)
160		}
161		if it.Content != "跟进1号机检修" || it.Constraints != "需停电窗口" || it.FollowOwner != "李四" {
162			t.Fatalf("字段应去掉首尾空白：%+v", it)
163		}
164	
165		// 限制条件可以为空。
166		if _, err := f.svc.AddItem(a.ID, "巡检记录归档", SeverityNormal, "", "王五"); err != nil {
167			t.Fatalf("限制条件应可为空：%v", err)
168		}
169	
170		if _, err := f.svc.UpdateItem(it.ID, "新内容", SeverityUrgent, "", "赵六"); err != nil {
171			t.Fatalf("结束前应可修改：%v", err)
172		}
173		if _, err := f.svc.CloseItem(it.ID, "张三"); err != nil {
174			t.Fatalf("结束前应可关闭：%v", err)
175		}
176		if _, err := f.svc.CloseItem(it.ID, "张三"); !errors.Is(err, ErrHandoverState) {
177			t.Fatalf("重复关闭应报错，got %v", err)
178		}
179		if _, err := f.svc.CloseItem("I999", "张三"); !errors.Is(err, ErrNotFound) {
180			t.Fatalf("不存在事项应 ErrNotFound，got %v", err)
181		}
182	
183		// 结束班次。
184		if _, err := f.svc.CloseShift(a.ID); err != nil {
185			t.Fatalf("close shift: %v", err)
186		}
187		// 已结束班次不能新增、修改、关闭事项。
188		if _, err := f.svc.AddItem(a.ID, "x", SeverityNormal, "", "y"); !errors.Is(err, ErrShiftClosed) {
189			t.Fatalf("已结束班次新增应报错，got %v", err)
190		}
191		if _, err := f.svc.UpdateItem(it.ID, "篡改", SeverityNormal, "", "y"); !errors.Is(err, ErrShiftClosed) {
192			t.Fatalf("已结束班次事项内容不能修改，got %v", err)
193		}
194		if _, err := f.svc.CloseItem("I002", "张三"); !errors.Is(err, ErrShiftClosed) {
195			t.Fatalf("已结束班次事项关闭状态不能修改，got %v", err)
196		}
197	
198		// 已关闭事项仍保留在结束时记录中。
199		rep, err := f.svc.ShiftReport(a.ID)
200		if err != nil {
201			t.Fatalf("report: %v", err)
202		}
203		if !rep.ItemsAtClose {
204			t.Fatalf("已结束班次应展示结束时记录")
205		}
206		if len(rep.CloseItems) != 2 {
207			t.Fatalf("已关闭事项也应保留在结束时记录中，期望2项，got %d", len(rep.CloseItems))
208		}
209		foundClosed := false
210		for _, x := range rep.CloseItems {
211			if x.ItemID == it.ID && x.Closed {
212				foundClosed = true
213			}
214		}
215		if !foundClosed {
216			t.Fatalf("结束时记录应展示关闭情况")
217		}
218	}
219	
220	func TestEmptyListCanCloseAndHandoverCompletes(t *testing.T) {
221		f := newFixture(t)
222		a := mustShift(t, f, "调度", "张三", tsDay(2, 8, 0), tsDay(2, 16, 0), "")
223		b := mustShift(t, f, "调度", "李四", tsDay(2, 16, 0), tsDay(2, 23, 0), "")
224	
225		// 空清单也能结束班次。
226		if _, err := f.svc.CloseShift(a.ID); err != nil {
227			t.Fatalf("空清单应能结束班次：%v", err)
228		}
229		h, err := f.svc.CreateHandover(a.ID, b.ID)
230		if err != nil {
231			t.Fatalf("空清单交接：%v", err)
232		}
233		if !h.Completed() {
234			t.Fatalf("空清单交接应直接完成")
235		}
236	}
237	
238	// 构建一个交班班次（含若干未关闭事项）并结束，返回接班班次。
239	func prepareHandover(t *testing.T, f *fixture) (Shift, Shift, []Item) {
240		t.Helper()
241		a := mustShift(t, f, "调度", "张三", tsDay(2, 8, 0), tsDay(2, 16, 0), "")
242		b := mustShift(t, f, "调度", "李四", tsDay(2, 16, 0), tsDay(2, 23, 0), "")
243		var items []Item
244		for _, c := range []string{"事项甲", "事项乙", "事项丙"} {
245			it, err := f.svc.AddItem(a.ID, c, SeverityNormal, "", "李四")
246			if err != nil {
247				t.Fatalf("add item: %v", err)
248			}
249			items = append(items, it)
250		}
251		// 关闭一项，验证只有未关闭事项进入清单。
252		if _, err := f.svc.CloseItem(items[2].ID, "张三"); err != nil {
253			t.Fatalf("close: %v", err)
254		}
255		if _, err := f.svc.CloseShift(a.ID); err != nil {
256			t.Fatalf("close: %v", err)
257		}
258		return a, b, items
259	}
260	
261	func TestHandoverCreationRules(t *testing.T) {
262		f := newFixture(t)
263		a, b, items := prepareHandover(t, f)
264	
265		h, err := f.svc.CreateHandover(a.ID, b.ID)
266		if err != nil {
267			t.Fatalf("create handover: %v", err)
268		}
269		if h.ID != "H001" {
270			t.Fatalf("交接稳定编号应为 H001，got %s", h.ID)
271		}
272		if len(h.Entries) != 2 {
273			t.Fatalf("只有未关闭事项进入待交接清单，期望2项，got %d", len(h.Entries))
274		}
275		for _, e := range h.Entries {
276			if e.ItemID == items[2].ID {
277				t.Fatalf("已关闭事项不应进入清单")
278			}
279			if e.Status != EntryPending {
280				t.Fatalf("初始应为待处理")
281			}
282		}
283	
284		// 重复发起同一对象：返回已有记录。
285		h2, err := f.svc.CreateHandover(a.ID, b.ID)
286		if !errors.Is(err, ErrHandoverExists) || h2.ID != h.ID {
287			t.Fatalf("重复发起应返回已有记录 ErrHandoverExists，got %v id=%s", err, h2.ID)
288		}
289	
290		// 改换对象：报错。
291		c := mustShift(t, f, "调度", "王五", tsDay(3, 0, 0), tsDay(3, 8, 0), "")
292		if _, err := f.svc.CreateHandover(a.ID, c.ID); !errors.Is(err, ErrHandoverTarget) {
293			t.Fatalf("改换接班对象应报错，got %v", err)
294		}
295	
296		// 不能交给自身。
297		if _, err := f.svc.CreateHandover(b.ID, b.ID); !errors.Is(err, ErrSameShift) {
298			// b 未结束，先命中自身校验。
299			t.Fatalf("交给自身应报错，got %v", err)
300		}
301		// 不能交给其他岗位：改用一个从未发起过交接的交班班次 c，首次交接仍按
302		// 岗位不符拒绝（同岗位要求对首次交接保留）。
303		other := mustShift(t, f, "巡检", "赵六", tsDay(2, 16, 0), tsDay(2, 23, 0), "")
304		if _, err := f.svc.CreateHandover(c.ID, other.ID); !errors.Is(err, ErrPositionMismatch) {
305			t.Fatalf("首次交接给其他岗位应报错，got %v", err)
306		}
307		// 已有交接记录时改指其他岗位的班次，按改换接班对象拒绝并指出原接班班次，
308		// 不再产生第二条交接（同岗位校验只对首次交接保留）。
309		if _, err := f.svc.CreateHandover(a.ID, other.ID); !errors.Is(err, ErrHandoverTarget) {
310			t.Fatalf("已有交接时改指其他岗位应按改换对象拒绝，got %v", err)
311		}
312		// 接班班次必须尚未结束：用一个没有接班交接的班次 d，先结束再作为接班对象。
313		d := mustShift(t, f, "调度", "钱七", tsDay(3, 8, 0), tsDay(3, 16, 0), "")
314		if _, err := f.svc.CloseShift(d.ID); err != nil {
315			t.Fatalf("close d: %v", err)
316		}
317		if _, err := f.svc.CreateHandover(c.ID, d.ID); !errors.Is(err, ErrShiftClosed) {
318			t.Fatalf("已结束的接班班次应报错，got %v", err)
319		}
320		// 交班班次未结束不能发起。
321		if _, err := f.svc.CreateHandover(c.ID, "S999"); !errors.Is(err, ErrNotFound) {
322			t.Fatalf("不存在接班班次应 ErrNotFound，got %v", err)
323		}
324		// 交班班次未结束时即使接班班次合法也不能发起。
325		open := mustShift(t, f, "调度", "孙八", tsDay(3, 16, 0), tsDay(4, 0, 0), "")
326		if _, err := f.svc.CreateHandover(c.ID, open.ID); !errors.Is(err, ErrShiftNotClosed) {
327			t.Fatalf("交班班次未结束应报 ErrShiftNotClosed，got %v", err)
328		}
329	}
330	
331	// TestRecreateHandoverAfterToShiftClosed：某次交接全部处理完成、接班班次随后
332	// 结束（事项又在后续班次关闭或继续流转）后，用原交班/接班编号重复发起必须视为
333	// 成功返回已有记录：原交接编号、两班关系、发起与完成时间、各事项当时的确认/
334	// 跟踪结果、处理人、处理时间以及退回与补充经过全部沿用原值，不重新挑选清单、
335	// 不重新接收、不移动事项、不追加经过。改换接班对象（无论新对象是否结束）一律
336	// 拒绝并指出原接班班次，且不得生成第二条交接；不存在的编号仍然报错。
337	func TestRecreateHandoverAfterToShiftClosed(t *testing.T) {
338		f := newFixture(t)
339		a, b, items := prepareHandover(t, f)
340		h1, err := f.svc.CreateHandover(a.ID, b.ID)
341		if err != nil {
342			t.Fatalf("create: %v", err)
343		}
344		idA, idB := items[0].ID, items[1].ID
345	
346		// 乙先退回、交班人补充后再继续跟踪，保留一轮退回/补充经过；甲确认接收。
347		if _, err := f.svc.ProcessEntry(h1.ID, idB, ActionReturn, "李四", "需要补充细节", "", ""); err != nil {
348			t.Fatalf("return: %v", err)
349		}
350		if _, err := f.svc.ResubmitReturned(h1.ID, idB, "张三", "补充说明如下"); err != nil {
351			t.Fatalf("resubmit: %v", err)
352		}
353		if _, err := f.svc.ProcessEntry(h1.ID, idA, ActionConfirm, "李四", "", "", ""); err != nil {
354			t.Fatalf("confirm: %v", err)
355		}
356		if _, err := f.svc.ProcessEntry(h1.ID, idB, ActionTrack, "李四", "", "继续盯压力", "王五"); err != nil {
357			t.Fatalf("track: %v", err)
358		}
359		h1, _ = f.svc.GetHandover(h1.ID)
360		if !h1.Completed() || h1.CompletedAt == nil {
361			t.Fatalf("全部处理后交接应已完成")
362		}
363		createdAt, completedAt := h1.CreatedAt, *h1.CompletedAt
364	
365		// 接班班次结束；事项继续流转到下一班 c，甲在 c 关闭。
366		if _, err := f.svc.CloseShift(b.ID); err != nil {
367			t.Fatalf("close b: %v", err)
368		}
369		c := mustShift(t, f, "调度", "赵六", tsDay(2, 23, 0), tsDay(3, 7, 0), "")
370		h2, err := f.svc.CreateHandover(b.ID, c.ID)
371		if err != nil {
372			t.Fatalf("chain handover: %v", err)
373		}
374		if _, err := f.svc.ProcessEntry(h2.ID, idA, ActionConfirm, "赵六", "", "", ""); err != nil {
375			t.Fatalf("confirm on c: %v", err)
376		}
377		if _, err := f.svc.ProcessEntry(h2.ID, idB, ActionTrack, "赵六", "", "持续跟进", "孙七"); err != nil {
378			t.Fatalf("track on c: %v", err)
379		}
380		if _, err := f.svc.CloseItem(idA, "赵六"); err != nil {
381			t.Fatalf("close item on c: %v", err)
382		}
383	
384		snapshot := func() string {
385			raw, err := json.Marshal(f.store.data)
386			if err != nil {
387				t.Fatalf("marshal: %v", err)
388			}
389			return string(raw)
390		}
391		before := snapshot()
392	
393		// 用原来的交班、接班编号重复发起：返回原记录（ErrHandoverExists），命令行
394		// 据此视为成功；即使接班班次 b 已结束也不再报“接班班次已结束”。
395		again, err := f.svc.CreateHandover(a.ID, b.ID)
396		if !errors.Is(err, ErrHandoverExists) {
397			t.Fatalf("接班班次结束后重复发起应返回 ErrHandoverExists，got %v", err)
398		}
399		stored, _ := f.svc.GetHandover(h1.ID)
400		if again.ID != h1.ID || again.FromShiftID != a.ID || again.ToShiftID != b.ID {
401			t.Fatalf("应返回原交接 %s 及原两班关系，got %+v", h1.ID, again)
402		}
403		if !again.CreatedAt.Equal(createdAt) || again.CompletedAt == nil || !again.CompletedAt.Equal(completedAt) {
404			t.Fatalf("发起时间与完成时间应沿用原值：created %v->%v completed %v->%v",
405				createdAt, again.CreatedAt, completedAt, again.CompletedAt)
406		}
407		if len(again.Entries) != 2 {
408			t.Fatalf("仍应展示原交接的2项清单，而不是按最新班次重新挑选，got %d", len(again.Entries))
409		}
410		got := map[string]HandoverEntry{}
411		for _, e := range again.Entries {
412			got[e.ItemID] = e
413		}
414		ea, eb := got[idA], got[idB]
415		if ea.Status != EntryConfirmed || ea.Operator != "李四" || ea.ProcessedAt == nil {
416			t.Fatalf("甲的确认结果/处理人/处理时间应沿用原值：%+v", ea)
417		}
418		if eb.Status != EntryTracking || eb.Operator != "李四" || eb.ProcessedAt == nil ||
419			eb.TrackingNote != "继续盯压力" || eb.FollowOwner != "王五" {
420			t.Fatalf("乙的继续跟踪结果应沿用原值：%+v", eb)
421		}
422		if len(eb.Rounds) != 1 {
423			t.Fatalf("退回与补充经过应保留，got %d 轮", len(eb.Rounds))
424		}
425		r := eb.Rounds[0]
426		if r.Reason != "需要补充细节" || r.ReturnOperator != "李四" ||
427			r.Supplement != "补充说明如下" || r.SupplementOperator != "张三" ||
428			r.ResubmittedAt == nil {
429			t.Fatalf("退回原因、补充说明、补充人与重新提交时间应原样保留：%+v", r)
430		}
431		// 返回的记录与存储中的原记录逐项一致。
432		if fmt.Sprintf("%+v", again) != fmt.Sprintf("%+v", stored) {
433			t.Fatalf("返回内容应为保存的完整原记录\nwant %+v\ngot  %+v", stored, again)
434		}
435	
436		// 重复返回不改动任何数据：不生成新交接、不移动事项、不追加事件或经过。
437		if after := snapshot(); after != before {
438			t.Fatalf("重复发起不得写入或移动任何数据\nbefore %s\nafter  %s", before, after)
439		}
440		if hs := f.svc.ListHandovers(); len(hs) != 2 {
441			t.Fatalf("不应生成第二条交接，期望仍为2条，got %d", len(hs))
442		}
443	
444		// 改换为一个确实存在、但已结束的班次：仍按改换对象拒绝并指出原接班班次，
445		// 不能因为新对象已结束而报“接班班次已结束”，更不能产生第二条交接。
446		d := mustShift(t, f, "调度", "钱七", tsDay(3, 8, 0), tsDay(3, 16, 0), "")
447		if _, err := f.svc.CloseShift(d.ID); err != nil {
448			t.Fatalf("close d: %v", err)
449		}
450		_, err = f.svc.CreateHandover(a.ID, d.ID)
451		if !errors.Is(err, ErrHandoverTarget) || !strings.Contains(err.Error(), b.ID) {
452			t.Fatalf("改换为已结束班次应报 ErrHandoverTarget 并指出原接班班次 %s，got %v", b.ID, err)
453		}
454	
455		// 改换为尚未结束的其他班次同样拒绝。
456		open := mustShift(t, f, "调度", "孙八", tsDay(3, 16, 0), tsDay(4, 0, 0), "")
457		if _, err := f.svc.CreateHandover(a.ID, open.ID); !errors.Is(err, ErrHandoverTarget) {
458			t.Fatalf("改换为未结束班次也应报 ErrHandoverTarget，got %v", err)
459		}
460		// 改指其他岗位的现存班次同样按改换对象拒绝（同岗位等要求只对首次交接保留）。
461		otherPos := mustShift(t, f, "巡检", "周九", tsDay(3, 8, 0), tsDay(3, 16, 0), "")
462		if _, err := f.svc.CreateHandover(a.ID, otherPos.ID); !errors.Is(err, ErrHandoverTarget) {
463			t.Fatalf("已有交接时改指其他岗位应按改换对象拒绝，got %v", err)
464		}
465		if hs := f.svc.ListHandovers(); len(hs) != 2 {
466			t.Fatalf("改换对象不得产生第二条交接，got %d 条", len(hs))
467		}
468	
469		// 编号错误不能被已有记录掩盖。
470		if _, err := f.svc.CreateHandover(a.ID, "S999"); !errors.Is(err, ErrNotFound) {
471			t.Fatalf("接班编号不存在应报 ErrNotFound，got %v", err)
472		}
473		if _, err := f.svc.CreateHandover("S999", b.ID); !errors.Is(err, ErrNotFound) {
474			t.Fatalf("交班编号不存在应报 ErrNotFound，got %v", err)
475		}
476		if _, err := f.svc.CreateHandover("S999", "S998"); !errors.Is(err, ErrNotFound) {
477			t.Fatalf("编号均不存在应报 ErrNotFound，got %v", err)
478		}
479		if hs := f.svc.ListHandovers(); len(hs) != 2 {
480			t.Fatalf("报错后交接数量应不变，got %d", len(hs))
481		}
482	}
483	
484	// TestRecreateEmptyHandoverAfterToShiftClosed：发起时即完成的空清单交接，
485	// 在接班班次结束后重复发起也应返回原记录与原完成时间。
486	func TestRecreateEmptyHandoverAfterToShiftClosed(t *testing.T) {
487		f := newFixture(t)
488		a := mustShift(t, f, "调度", "张三", tsDay(2, 8, 0), tsDay(2, 16, 0), "")
489		b := mustShift(t, f, "调度", "李四", tsDay(2, 16, 0), tsDay(2, 23, 0), "")
490		if _, err := f.svc.CloseShift(a.ID); err != nil {
491			t.Fatalf("close a: %v", err)
492		}
493		h, err := f.svc.CreateHandover(a.ID, b.ID)
494		if err != nil {
495			t.Fatalf("create: %v", err)
496		}
497		if len(h.Entries) != 0 || !h.Completed() || h.CompletedAt == nil {
498			t.Fatalf("空清单交接应发起即完成：%+v", h)
499		}
500		completedAt := *h.CompletedAt
501		if _, err := f.svc.CloseShift(b.ID); err != nil {
502			t.Fatalf("close b: %v", err)
503		}
504	
505		again, err := f.svc.CreateHandover(a.ID, b.ID)
506		if !errors.Is(err, ErrHandoverExists) {
507			t.Fatalf("空清单交接在接班班次结束后重复发起应返回原记录，got %v", err)
508		}
509		if again.ID != h.ID || len(again.Entries) != 0 ||
510			again.CompletedAt == nil || !again.CompletedAt.Equal(completedAt) {
511			t.Fatalf("应返回原空清单交接与原完成时间：%+v", again)
512		}
513	}
514	
515	func TestHandoverStartConstraintAndOverlapNote(t *testing.T) {
516		f := newFixture(t)
517		// 交班班次 16:00-23:00；接班班次开始时间早于交班开始、但不重叠：10:00-16:00（端点相接）。
518		a := mustShift(t, f, "调度", "张三", tsDay(2, 16, 0), tsDay(2, 23, 0), "")
519		early := mustShift(t, f, "调度", "李四", tsDay(2, 10, 0), tsDay(2, 16, 0), "")
520		if _, err := f.svc.AddItem(a.ID, "x", SeverityNormal, "", "y"); err != nil {
521			t.Fatalf("add: %v", err)
522		}
523		if _, err := f.svc.CloseShift(a.ID); err != nil {
524			t.Fatalf("close: %v", err)
525		}
526		if _, err := f.svc.CreateHandover(a.ID, early.ID); !errors.Is(err, ErrInvalidInput) {
527			t.Fatalf("接班开始早于交班开始应报错，got %v", err)
528		}
529	
530		// 重叠但有说明时允许交接。

file.content:
package handover

import (
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"
)

type fixture struct {
	svc   *Service
	store *Store
	clock time.Time
}

func newFixture(t *testing.T) *fixture {
	t.Helper()
	dir := t.TempDir()
	store, err := Open(filepath.Join(dir, "data.json"))
	if err != nil {
		t.Fatalf("open: %v", err)
	}
	svc := NewService(store)
	f := &fixture{
		svc:   svc,
		store: store,
		clock: time.Date(2026, 10, 2, 8, 0, 0, 0, time.FixedZone("CST", 8*3600)),
	}
	svc.nowAt(func() time.Time {
		f.clock = f.clock.Add(time.Minute)
		return f.clock
	})
	return f
}

// reopen 模拟退出后重新打开，数据与处理进度必须仍在。
func (f *fixture) reopen(t *testing.T) {
	t.Helper()
	store, err := Open(f.store.Path())
	if err != nil {
		t.Fatalf("reopen: %v", err)
	}
	svc := NewService(store)
	svc.nowAt(f.svc.now)
	f.store = store
	f.svc = svc
}

func tsDay(day, hour, min int) time.Time {
	return time.Date(2026, 10, day, hour, min, 0, 0, time.FixedZone("CST", 8*3600))
}

func ts(hour, min int) time.Time { return tsDay(2, hour, min) }

func mustShift(t *testing.T, f *fixture, position, owner string, s, e time.Time, note string) Shift {
	t.Helper()
	sh, err := f.svc.CreateShift(position, owner, s, e, note)
	if err != nil {
		t.Fatalf("create shift: %v", err)
	}
	return sh
}

func TestCreateShiftValidation(t *testing.T) {
	f := newFixture(t)

	if _, err := f.svc.CreateShift("   ", "张三", ts(8, 0), ts(16, 0), ""); !errors.Is(err, ErrInvalidInput) {
		t.Fatalf("空白岗位应报错， got %v", err)
	}
	if _, err := f.svc.CreateShift("调度", "  ", ts(8, 0), ts(16, 0), ""); !errors.Is(err, ErrInvalidInput) {
		t.Fatalf("空白负责人应报错，got %v", err)
	}
	if _, err := f.svc.CreateShift("调度", "张三", ts(16, 0), ts(8, 0), ""); !errors.Is(err, ErrInvalidInput) {
		t.Fatalf("结束早于开始应报错，got %v", err)
	}
	if _, err := f.svc.CreateShift("调度", "张三", ts(8, 0), ts(8, 0), ""); !errors.Is(err, ErrInvalidInput) {
		t.Fatalf("结束等于开始应报错，got %v", err)
	}

	a := mustShift(t, f, "调度", "张三", ts(8, 0), ts(16, 0), "")
	b := mustShift(t, f, "调度", "李四", ts(16, 0), ts(23, 0), "")
	if a.ID != "S001" || b.ID != "S002" {
		t.Fatalf("稳定编号错误：%s %s", a.ID, b.ID)
	}
}

func TestOverlapEndpointAndPositions(t *testing.T) {
	f := newFixture(t)
	mustShift(t, f, "调度", "张三", ts(8, 0), ts(16, 0), "")

	// 重叠但没有说明：报错。
	if _, err := f.svc.CreateShift("调度", "王五", ts(15, 0), ts(22, 0), "   "); !errors.Is(err, ErrOverlap) {
		t.Fatalf("重叠无说明应报 ErrOverlap，got %v", err)
	}

	// 重叠且提供说明：成功并保存说明。
	overlap, err := f.svc.CreateShift("调度", "王五", ts(15, 0), ts(22, 0), "突发抢修，两班并行一小时")
	if err != nil {
		t.Fatalf("重叠带说明应成功，got %v", err)
	}
	notes := f.svc.OverlapNotes(overlap.ID)
	if len(notes) != 1 || notes[0].Note != "突发抢修，两班并行一小时" {
		t.Fatalf("应能查看说明与涉及班次，got %+v", notes)
	}
	if !((notes[0].ShiftA == "S001" && notes[0].ShiftB == overlap.ID) ||
		(notes[0].ShiftA == overlap.ID && notes[0].ShiftB == "S001")) {
		t.Fatalf("说明应涉及两个重叠班次，got %+v", notes[0])
	}

	// 不同岗位同时间段互不影响。
	if _, err := f.svc.CreateShift("巡检", "赵六", ts(8, 30), ts(15, 30), ""); err != nil {
		t.Fatalf("不同岗位不应判定重叠：%v", err)
	}
}

func TestAddOverlapNoteValidation(t *testing.T) {
	f := newFixture(t)
	a := mustShift(t, f, "调度", "张三", ts(8, 0), ts(16, 0), "")
	b := mustShift(t, f, "调度", "李四", ts(16, 0), ts(23, 0), "")
	other := mustShift(t, f, "巡检", "赵六", ts(8, 0), ts(16, 0), "")

	if _, err := f.svc.AddOverlapNote(a.ID, b.ID, "相邻"); !errors.Is(err, ErrInvalidInput) {
		t.Fatalf("不重叠班次（端点相接）应拒绝说明，got %v", err)
	}
	if _, err := f.svc.AddOverlapNote(a.ID, other.ID, "跨岗位"); !errors.Is(err, ErrPositionMismatch) {
		t.Fatalf("不同岗位应拒绝，got %v", err)
	}
	if _, err := f.svc.AddOverlapNote(a.ID, "S999", "x"); !errors.Is(err, ErrNotFound) {
		t.Fatalf("不存在编号应 ErrNotFound，got %v", err)
	}
	if _, err := f.svc.AddOverlapNote(a.ID, a.ID, "自身"); !errors.Is(err, ErrInvalidInput) {
		t.Fatalf("同一班次应拒绝，got %v", err)
	}
}

func TestItemLifecycleAndClosedShiftImmutability(t *testing.T) {
	f := newFixture(t)
	a := mustShift(t, f, "调度", "张三", ts(8, 0), ts(16, 0), "")

	if _, err := f.svc.AddItem(a.ID, "  ", SeverityNormal, "", "李四"); !errors.Is(err, ErrInvalidInput) {
		t.Fatalf("空白内容应报错，got %v", err)
	}
	if _, err := f.svc.AddItem(a.ID, "跟进1号机", Severity("bad"), "", "李四"); !errors.Is(err, ErrInvalidInput) {
		t.Fatalf("非法严重程度应报错，got %v", err)
	}
	if _, err := f.svc.AddItem(a.ID, "跟进1号机", SeverityNormal, "", "  "); !errors.Is(err, ErrInvalidInput) {
		t.Fatalf("空白后续负责人应报错，got %v", err)
	}

	it, err := f.svc.AddItem(a.ID, "  跟进1号机检修 ", SeverityImportant, "  需停电窗口 ", " 李四 ")
	if err != nil {
		t.Fatalf("add item: %v", err)
	}
	if it.ID != "I001" {
		t.Fatalf("事项稳定编号应为 I001，got %s", it.ID)
	}
	if it.Content != "跟进1号机检修" || it.Constraints != "需停电窗口" || it.FollowOwner != "李四" {
		t.Fatalf("字段应去掉首尾空白：%+v", it)
	}

	// 限制条件可以为空。
	if _, err := f.svc.AddItem(a.ID, "巡检记录归档", SeverityNormal, "", "王五"); err != nil {
		t.Fatalf("限制条件应可为空：%v", err)
	}

	if _, err := f.svc.UpdateItem(it.ID, "新内容", SeverityUrgent, "", "赵六"); err != nil {
		t.Fatalf("结束前应可修改：%v", err)
	}
	if _, err := f.svc.CloseItem(it.ID, "张三"); err != nil {
		t.Fatalf("结束前应可关闭：%v", err)
	}
	if _, err := f.svc.CloseItem(it.ID, "张三"); !errors.Is(err, ErrHandoverState) {
		t.Fatalf("重复关闭应报错，got %v", err)
	}
	if _, err := f.svc.CloseItem("I999", "张三"); !errors.Is(err, ErrNotFound) {
		t.Fatalf("不存在事项应 ErrNotFound，got %v", err)
	}

	// 结束班次。
	if _, err := f.svc.CloseShift(a.ID); err != nil {
		t.Fatalf("close shift: %v", err)
	}
	// 已结束班次不能新增、修改、关闭事项。
	if _, err := f.svc.AddItem(a.ID, "x", SeverityNormal, "", "y"); !errors.Is(err, ErrShiftClosed) {
		t.Fatalf("已结束班次新增应报错，got %v", err)
	}
	if _, err := f.svc.UpdateItem(it.ID, "篡改", SeverityNormal, "", "y"); !errors.Is(err, ErrShiftClosed) {
		t.Fatalf("已结束班次事项内容不能修改，got %v", err)
	}
	if _, err := f.svc.CloseItem("I002", "张三"); !errors.Is(err, ErrShiftClosed) {
		t.Fatalf("已结束班次事项关闭状态不能修改，got %v", err)
	}

	// 已关闭事项仍保留在结束时记录中。
	rep, err := f.svc.ShiftReport(a.ID)
	if err != nil {
		t.Fatalf("report: %v", err)
	}
	if !rep.ItemsAtClose {
		t.Fatalf("已结束班次应展示结束时记录")
	}
	if len(rep.CloseItems) != 2 {
		t.Fatalf("已关闭事项也应保留在结束时记录中，期望2项，got %d", len(rep.CloseItems))
	}
	foundClosed := false
	for _, x := range rep.CloseItems {
		if x.ItemID == it.ID && x.Closed {
			foundClosed = true
		}
	}
	if !foundClosed {
		t.Fatalf("结束时记录应展示关闭情况")
	}
}

